    proxy_read_timeout 90;

    location / {
        root  /home;
        index index.php;
        try_files $uri $uri/ /index.php?$query_string;

        limit_conn perip 100;
        limit_req zone=dynamic burst=10 nodelay;

        if (!-f $request_filename){
            set $rule_1 1$rule_1;
        }

        if (!-d $request_filename){
            set $rule_1 2$rule_1;
        }

        server_tokens off;
    }

    location ~ \.php$ {
        root           /home;
        include fastcgi_params;
        try_files $fastcgi_script_name =404;
        proxy_send_timeout 600; # время ожидания при передаче запроса
        proxy_read_timeout 600; # время ожидания при чтении ответа
        fastcgi_pass unix:/run/php/php7.1-fpm.sock;
        fastcgi_index index.php;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
    }

    access_log off;

    location /doc {
        root  /home;
        autoindex on;
        allow 127.0.0.1;
        deny all;
    }

    location = /favicon.ico {
        log_not_found off;
        access_log off;
        }
        location = /robots.txt {
        allow all;
        log_not_found off;
        access_log off;
    }
    location /styles/images {
        root  /home;
            autoindex on;
    }
    error_page  404              /404.html;
    error_page  500 502 503 504  /50x.html;

    rewrite ^/sitemap.xml$ /sitemap/sitemap.xml;
    rewrite ^/atom/(.*) /atom$1;

    # Cached Images
    location ~* \.(jpg|jpeg|gif|bmp|ico|png|css|js|swf)$ {
        root         /home;
        access_log   off;
        expires      1h;
        add_header   Cache-Control  public;
    }

    location ~ \/admin|backup\/ {
        deny all;
        #allow YOUR_IP;
    }

    # Deny folder (Sec. lvl1)
    location ~  \/(install|library)\/ {
        deny all;
    }

    # deny access to .htaccess files, if Apache&#039;s document root
    # concurs with nginx&#039;s one
    # deny sql,tpl,db,inc,log
    location ~ /\.ht {
        deny  all;
    }

    location ~ \.(.*sql|tpl|inc|db|log)|(config|common).php$ {
        deny  all;
    }
